import{_ as i,c as n,o as r,a2 as t}from"./chunks/framework.CIiVzG-O.js";const h=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/faq.md","filePath":"de/guide/faq.md","lastUpdated":1793163976000}'),a={name:"de/guide/faq.md"};function s(p,e,o,l,u,d){return r(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>F: Was ist NueZip?</p><p>A: NueZip ist ein professioneller Archivmanager für macOS, der die Komprimierung und Extraktion mehrerer Archivformate unterstützt, darunter RAR, ZIP, 7-Zip, TAR, GZIP und BZIP2.</p><p>F: Welche macOS-Versionen werden unterstützt?</p><p>A: NueZip benötigt macOS 14 Sonoma oder neuer und ist für Apple Silicon (M-Serie)-Chips optimiert.</p><p>F: Wie lade ich NueZip herunter und installiere es?</p><p>A: Laden Sie es aus dem <a href="https://apps.apple.com/app/id6785846417" target="_blank" rel="noreferrer">Mac App Store</a> (empfohlen) oder holen Sie sich das neueste Release von <a href="https://github.com/nuezip/nuezip/releases" target="_blank" rel="noreferrer">GitHub Releases</a>.</p><p>F: Ist NueZip kostenlos?</p><p>A: NueZip bietet eine kostenlose Testversion mit Kernfunktionen. Ein einmaliger Kauf schaltet den vollen Funktionsumfang frei, einschließlich Stapelverarbeitung, Archiv-Reparatur und erweiterter Verschlüsselung.</p><p>F: Welche Formate werden unterstützt?</p><p>A: <strong>Lesen</strong>: RAR, ZIP, 7-Zip, TAR, GZIP, BZIP2, XZ, Zstandard<br><strong>Schreiben (komprimieren)</strong>: ZIP, 7-Zip, TAR, GZIP, BZIP2, XZ, Zstandard<br> Siehe <a href="/de/guide/introduction.html">Einführung</a> für die vollständige Formatmatrix.</p><p>F: Kann NueZip RAR-Archive erstellen?</p><p>A: Nein. NueZip kann RAR-Archive <strong>lesen</strong> (einschließlich Multi-Volume- und reparierter Archive), aber die RAR-Komprimierung wird aufgrund von Lizenzbeschränkungen nicht unterstützt.</p><p>F: Ist NueZip sicher für vertrauliche Dateien?</p><p>A: Ja. NueZip arbeitet vollständig offline. Alle Vorgänge laufen lokal auf Ihrem Mac. AES-256-Verschlüsselung ist für passwortgeschützte ZIP-Archive verfügbar.</p><p>F: Lädt NueZip meine Dateien in die Cloud hoch?</p><p>A: Nein. NueZip ist eine vollständig offline arbeitende Anwendung. Ihre Dateien werden niemals irgendwo hochgeladen. Für Komprimierung oder Extraktion ist keine Internetverbindung erforderlich.</p><p>F: Wie aktualisiere ich die App?</p><p>A: Aktualisieren Sie über den Mac App Store (automatisch) oder laden Sie das neueste Release von GitHub Releases herunter.</p><p>F: Wie melde ich Fehler oder fordere Funktionen an?</p><p>A: Öffnen Sie ein Issue im <a href="https://github.com/nuezip/nuezip/issues" target="_blank" rel="noreferrer">GitHub-Repository</a>. Bitte geben Sie Ihre macOS-Version, NueZip-Version und Schritte zur Reproduktion an.</p><p>F: Wo werden Protokolle und Daten gespeichert?</p><p>A: Bei sandboxed (App Store)-Builds:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Containers/com.w3cub.nuezip/Data/Library/Application Support/com.w3cub.nuezip/</span></span></code></pre></div><p>Entwicklungs-Builds schreiben Protokolle möglicherweise in die Konsole.</p><p>Wenn Sie weitere Antworten benötigen, öffnen Sie bitte ein Issue im Repository oder konsultieren Sie die vollständige Dokumentation.</p>',26)])])}const m=i(a,[["render",s]]);export{h as __pageData,m as default};
